/* Linux Drill question bank. All command examples are educational, not executed. */
window.LINUX_COMMANDS = [
  // ───────────────────────────── BEGINNER ─────────────────────────────
  {id:'pwd', level:'beginner', group:'filesystem', about:'Prints the absolute path of your current working directory.', syntax:'pwd', demo:'pwd', meaning:'Prints the full path of the current directory.', task:'Display the absolute path of the directory you are currently in.', answer:'pwd', wrong:['ls','cd ..','whoami'], tip:'pwd stands for print working directory; it does not list the files inside it.', examples:[['pwd -P','Show the physical path, resolving symbolic links.'],['cd /tmp && pwd','Change to /tmp and print the new working directory.']]},
  {id:'ls', level:'beginner', group:'filesystem', about:'Lists files and directories, with options for detail and hidden entries.', syntax:'ls [options] [path]', demo:'ls -la', meaning:'Lists directory entries in long format, including hidden files.', task:'List all entries in the current directory, including hidden ones, with details.', answer:'ls -la', wrong:['ls -l','ls -a','pwd'], tip:'-l means long format; -a includes names starting with a dot. Combine them for both.', examples:[['ls -lh','Show file sizes in a human-readable long listing.'],['ls /var/log','List entries under /var/log.']]},
  {id:'cd', level:'beginner', group:'filesystem', about:'Changes the current directory in the shell.', syntax:'cd [directory]', demo:'cd ..', meaning:'Moves the current shell to the parent directory.', task:'Move up one directory from your current location.', answer:'cd ..', wrong:['cd /','pwd','ls ..'], tip:'cd is a shell builtin. cd with no arguments usually goes to your home directory.', examples:[['cd ~/Documents','Enter Documents inside your home directory.'],['cd -','Return to the previous working directory.']]},
  {id:'mkdir', level:'beginner', group:'filesystem', about:'Creates one or more new directories.', syntax:'mkdir [options] directory', demo:'mkdir -p projects/demo', meaning:'Creates nested directories, including missing parent directories.', task:'Create projects/demo even if projects does not exist yet.', answer:'mkdir -p projects/demo', wrong:['mkdir projects/demo','touch projects/demo','cd projects/demo'], tip:'Without -p, mkdir fails if a required parent directory is missing.', examples:[['mkdir drafts','Create a folder called drafts.'],['mkdir -p a/b/c','Create an entire nested directory structure.']]},
  {id:'rmdir', level:'beginner', group:'filesystem', about:'Removes empty directories only.', syntax:'rmdir directory', demo:'rmdir old-folder', meaning:'Removes the directory old-folder only if it is empty.', task:'Remove an empty directory called old-folder without deleting any files.', answer:'rmdir old-folder', wrong:['rm -rf old-folder','touch old-folder','mkdir old-folder'], tip:'rmdir refuses to remove a nonempty directory; this is safer than a recursive rm.', examples:[['rmdir temp','Remove temp if it is empty.'],['rmdir -p a/b','Remove b, then a, when both become empty.']]},
  {id:'touch', level:'beginner', group:'filesystem', about:'Updates file timestamps and creates empty files if they do not exist.', syntax:'touch [options] file', demo:'touch notes.txt', meaning:'Creates notes.txt if missing, or updates its timestamps if it exists.', task:'Create an empty notes.txt file if it does not already exist.', answer:'touch notes.txt', wrong:['mkdir notes.txt','cat notes.txt','rm notes.txt'], tip:'touch does not erase existing file contents.', examples:[['touch a.txt b.txt','Create or update two files.'],['touch -c existing.txt','Update timestamps only if the file already exists.']]},
  {id:'cp', level:'beginner', group:'filesystem', about:'Copies files and, with the right option, directories.', syntax:'cp [options] source destination', demo:'cp -r assets backup/', meaning:'Recursively copies the assets directory into backup/.', task:'Copy the entire assets directory into the existing backup directory.', answer:'cp -r assets backup/', wrong:['cp assets backup/','mv assets backup/','cat assets > backup/'], tip:'-r is required for copying directories recursively. cp leaves the source in place.', examples:[['cp notes.txt copy.txt','Make a copy of a file.'],['cp -i source.txt dest.txt','Prompt before overwriting the destination.']]},
  {id:'mv', level:'beginner', group:'filesystem', about:'Moves or renames files and directories.', syntax:'mv [options] source destination', demo:'mv draft.txt final.txt', meaning:'Renames draft.txt to final.txt, or moves it if the destination is a path.', task:'Rename draft.txt to final.txt without keeping a copy under the old name.', answer:'mv draft.txt final.txt', wrong:['cp draft.txt final.txt','rm draft.txt','touch final.txt'], tip:'Unlike cp, mv typically removes the original directory entry as part of the move.', examples:[['mv photo.jpg images/','Move a file into a directory.'],['mv -i old.txt new.txt','Prompt before overwriting an existing target.']]},
  {id:'rm', level:'beginner', group:'filesystem', about:'Removes files; recursive deletion of directories requires extra care.', syntax:'rm [options] path', demo:'rm -i draft.txt', meaning:'Asks for confirmation before removing draft.txt.', task:'Delete draft.txt but ask for confirmation first.', answer:'rm -i draft.txt', wrong:['rm -f draft.txt','rmdir draft.txt','mv draft.txt .'], tip:'rm generally does not send files to a trash bin. Avoid rm -rf unless you fully understand the target.', examples:[['rm old.txt','Remove a file without prompting by default.'],['rm -r old-folder','Recursively remove a directory and its contents; use carefully.']]},
  {id:'cat', level:'beginner', group:'text', about:'Concatenates files and prints their contents to standard output.', syntax:'cat [file ...]', demo:'cat notes.txt', meaning:'Prints the contents of notes.txt to the terminal.', task:'Display the entire contents of notes.txt in the terminal.', answer:'cat notes.txt', wrong:['touch notes.txt','ls notes.txt','mkdir notes.txt'], tip:'For a long file, less is often easier to navigate than cat.', examples:[['cat first.txt second.txt','Display two files in order.'],['cat -n notes.txt','Display contents with line numbers.']]},
  {id:'less', level:'beginner', group:'text', about:'Opens a scrollable pager to read text without changing the file.', syntax:'less [file]', demo:'less system.log', meaning:'Opens system.log in an interactive, scrollable pager.', task:'Read a long log file one screen at a time, with the ability to scroll.', answer:'less system.log', wrong:['cat system.log','rm system.log','touch system.log'], tip:'Press q to quit less; use /pattern to search while viewing.', examples:[['less -N README.md','Show line numbers while paging.'],['less +G system.log','Open the file positioned at the end.']]},
  {id:'head', level:'beginner', group:'text', about:'Displays the beginning of a file or input stream.', syntax:'head [options] [file]', demo:'head -n 5 access.log', meaning:'Displays the first five lines of access.log.', task:'Print only the first five lines of access.log.', answer:'head -n 5 access.log', wrong:['tail -n 5 access.log','wc -l access.log','cat access.log'], tip:'Without -n, head normally displays the first 10 lines.', examples:[['head README.md','Show the first 10 lines.'],['head -c 100 file.txt','Show the first 100 bytes.']]},
  {id:'tail', level:'beginner', group:'text', about:'Displays the end of a file and can follow new lines as they arrive.', syntax:'tail [options] [file]', demo:'tail -f app.log', meaning:'Shows the last lines of app.log and keeps displaying appended lines.', task:'Watch new lines appear in app.log as the application writes them.', answer:'tail -f app.log', wrong:['head -f app.log','cat -f app.log','ls -f app.log'], tip:'Press Ctrl+C to stop following the log.', examples:[['tail -n 20 app.log','Show the last 20 lines.'],['tail -F app.log','Follow a log across file replacement or rotation.']]},
  {id:'echo', level:'beginner', group:'shell', about:'Prints text or expanded shell values to standard output.', syntax:'echo [text ...]', demo:'echo "$HOME"', meaning:'Prints the value of the HOME environment variable.', task:'Print your home-directory path using the HOME environment variable.', answer:'echo "$HOME"', wrong:['cat "$HOME"','pwd "$HOME"','cd "$HOME"'], tip:'Double quotes allow variable expansion; single quotes would print $HOME literally.', examples:[['echo Hello','Print Hello.'],['echo "Hello, $USER"','Print a greeting using the USER variable.']]},
  {id:'clear', level:'beginner', group:'shell', about:'Clears the visible terminal display without deleting files.', syntax:'clear', demo:'clear', meaning:'Clears the visible terminal screen.', task:'Clear the visible terminal screen before entering new commands.', answer:'clear', wrong:['rm *','exit','reset -f'], tip:'Clearing the display does not necessarily erase scrollback history.', examples:[['clear','Clear the current terminal display.'],['Ctrl+L','Many shells support this keyboard shortcut for clearing the screen.']]},
  {id:'man', level:'beginner', group:'help', about:'Displays manual pages for installed commands and topics.', syntax:'man command', demo:'man ls', meaning:'Opens the manual page for ls.', task:'Read the installed manual documentation for ls.', answer:'man ls', wrong:['ls --run','help cd ls','cat ls'], tip:'Press q to exit a man page. Not all minimal systems have all manual pages installed.', examples:[['man grep','Read grep documentation.'],['man 5 crontab','Open the crontab file-format manual (section 5).']]},
  {id:'whoami', level:'beginner', group:'system', about:'Prints the effective username of the current process.', syntax:'whoami', demo:'whoami', meaning:'Prints the effective username of the current user.', task:'Find out which effective username your shell is running as.', answer:'whoami', wrong:['hostname','pwd','date'], tip:'whoami is roughly equivalent to id -un; hostname refers to the computer, not the user.', examples:[['whoami','Show the effective username.'],['id -un','Another way to print the effective username.']]},
  {id:'id', level:'beginner', group:'system', about:'Shows numeric user and group IDs and group memberships.', syntax:'id [options] [user]', demo:'id', meaning:'Displays the current user ID, group ID, and group memberships.', task:'Show your UID, primary GID, and supplementary groups.', answer:'id', wrong:['whoami','hostname','groups -n'], tip:'UID identifies a user numerically; GID identifies a group.', examples:[['id -u','Print only the numeric user ID.'],['id -nG','Show names of groups you belong to.']]},
  {id:'date', level:'beginner', group:'system', about:'Displays or formats the system date and time.', syntax:'date [+FORMAT]', demo:'date +%Y-%m-%d', meaning:'Prints the current date in year-month-day format.', task:'Display today’s date using YYYY-MM-DD formatting.', answer:'date +%Y-%m-%d', wrong:['cal -y','time +%Y-%m-%d','uname -d'], tip:'The + introduces a format string. %Y is year, %m is month, and %d is day.', examples:[['date','Show the current date and time.'],['date -u','Show date and time in UTC.']]},
  {id:'cal', level:'beginner', group:'system', about:'Displays a text calendar when the utility is installed.', syntax:'cal [month] [year]', demo:'cal -y', meaning:'Displays a calendar for the entire current year.', task:'Display all twelve months of the current year as a calendar.', answer:'cal -y', wrong:['date -y','cal -m','uname -a'], tip:'cal is not installed by default on every Linux distribution.', examples:[['cal','Show a calendar for the current month.'],['cal 12 2026','Show the calendar for December 2026.']]},
  {id:'uname', level:'beginner', group:'system', about:'Prints kernel and system identity information.', syntax:'uname [options]', demo:'uname -r', meaning:'Prints the running kernel release version.', task:'Find the release version of the currently running Linux kernel.', answer:'uname -r', wrong:['whoami -r','hostname -r','date -r'], tip:'uname -a prints a wider set of kernel and machine information.', examples:[['uname -a','Show available kernel and machine details.'],['uname -m','Show the hardware architecture name.']]},
  {id:'hostname', level:'beginner', group:'system', about:'Displays the system hostname.', syntax:'hostname', demo:'hostname', meaning:'Prints the name assigned to the current host.', task:'Display the hostname of the machine you are using.', answer:'hostname', wrong:['whoami','pwd','id -u'], tip:'The hostname identifies the machine; whoami identifies your effective username.', examples:[['hostname','Show the short hostname.'],['hostname -f','Request the fully qualified domain name if it is configured.']]},
  {id:'df', level:'beginner', group:'system', about:'Reports filesystem space usage.', syntax:'df [options] [path]', demo:'df -h', meaning:'Shows free and used space on mounted filesystems in human-readable units.', task:'Check free disk space on mounted filesystems in GB/MB-style units.', answer:'df -h', wrong:['du -h','free -h','ls -h'], tip:'df measures filesystem capacity. du measures space used by files or folders.', examples:[['df -h /','Inspect space on the filesystem containing /.'],['df -i','Check inode use instead of byte capacity.']]},
  {id:'du', level:'beginner', group:'system', about:'Estimates the disk space used by files and directories.', syntax:'du [options] [path]', demo:'du -sh Downloads', meaning:'Displays the total disk usage of Downloads in human-readable units.', task:'Find the total space used by the Downloads folder in a readable single summary.', answer:'du -sh Downloads', wrong:['df -h Downloads','du -h Downloads','ls -lh Downloads'], tip:'-s summarizes; -h uses readable sizes. du can take time on large directories.', examples:[['du -sh *','Show summarized usage for each nonhidden entry in the current directory.'],['du -h -d 1 .','Show size totals one directory level deep on GNU du.']]},
  {id:'free', level:'beginner', group:'system', about:'Displays RAM and swap usage on Linux.', syntax:'free [options]', demo:'free -h', meaning:'Shows RAM and swap usage in human-readable units.', task:'Quickly check how much RAM and swap are used and available.', answer:'free -h', wrong:['df -h','du -sh /','top -f'], tip:'The available column is generally more useful than free alone when judging memory pressure.', examples:[['free -m','Show memory quantities in mebibytes.'],['free -h -s 2','Refresh memory statistics every two seconds.']]},
  {id:'history', level:'beginner', group:'shell', about:'Displays the shell’s command history (behavior depends on the shell).', syntax:'history', demo:'history', meaning:'Displays commands recorded in the current shell history.', task:'View commands you entered earlier in your Bash shell.', answer:'history', wrong:['man history','whoami','ps'], tip:'History is shell-specific. In Bash, history may not include other sessions until they are written.', examples:[['history 10','Show the most recent 10 Bash history entries.'],['history | tail -n 5','Show the last five displayed history entries.']]},
  {id:'which', level:'beginner', group:'help', about:'Locates an executable on PATH; it may not report shell aliases or functions reliably.', syntax:'which program', demo:'which python3', meaning:'Shows the PATH location of the python3 executable, if found.', task:'Find the executable file for python3 on your PATH.', answer:'which python3', wrong:['where python3','cat python3','pwd python3'], tip:'For shell aliases and builtins, type is often more informative than which.', examples:[['which ls','Locate the ls executable on PATH.'],['command -v python3','A shell-supported alternative to discover a command.']]},
  {id:'type', level:'beginner', group:'help', about:'Explains how the shell resolves a name: alias, function, builtin, or executable.', syntax:'type command', demo:'type cd', meaning:'Reports how the shell recognizes cd, usually as a builtin.', task:'Determine whether cd is a shell builtin, function, alias, or external executable.', answer:'type cd', wrong:['which -b cd','file cd','ls cd'], tip:'type is useful when which misses shell aliases, builtins, or functions.', examples:[['type ls','See how the shell resolves ls.'],['type -a python3','Show all available resolutions in Bash.']]},
  {id:'file', level:'beginner', group:'help', about:'Detects a file’s type by inspecting its contents and metadata.', syntax:'file [options] path', demo:'file image.png', meaning:'Identifies the type of image.png based on its content.', task:'Identify whether image.png is actually a PNG, without relying on its extension.', answer:'file image.png', wrong:['ls image.png','cat image.png','type image.png'], tip:'The file utility looks for content signatures; the extension alone may be misleading.', examples:[['file script.sh','Inspect what kind of file a script is.'],['file -i photo.jpg','Request MIME-style type information.']]},
  {id:'stat', level:'beginner', group:'filesystem', about:'Shows detailed metadata about a file or directory.', syntax:'stat path', demo:'stat report.txt', meaning:'Displays file metadata such as size, permissions, and timestamps.', task:'Inspect the size, inode, permissions, and timestamps of report.txt.', answer:'stat report.txt', wrong:['cat report.txt','touch report.txt','pwd report.txt'], tip:'stat reports metadata, whereas cat prints the file contents.', examples:[['stat -c %s report.txt','Print the file size in bytes on GNU stat.'],['stat -c %a report.txt','Print numeric permission bits on GNU stat.']]},
  // ──────────────────────────── INTERMEDIATE ──────────────────────────
  {id:'grep',level:'intermediate',group:'text',about:'Searches lines of text for a matching pattern.',syntax:'grep [options] PATTERN [file ...]',demo:'grep -n "error" app.log',meaning:'Prints matching lines from app.log with their line numbers.',task:'Find lines containing error in app.log and show their line numbers.',answer:'grep -n "error" app.log',wrong:['grep -c "error" app.log','find app.log -name "error"','sort app.log'],tip:'-n adds line numbers; -i ignores case; -r searches directories recursively.',examples:[['grep -i "warning" app.log','Find matches regardless of case.'],['grep -r "TODO" src/','Search file contents recursively under src/.']]},
  {id:'find',level:'intermediate',group:'filesystem',about:'Recursively searches directory trees for files matching tests.',syntax:'find PATH [tests] [actions]',demo:'find /var/log -name "*.log"',meaning:'Finds files and directories ending in .log below /var/log.',task:'Locate all names ending in .log within /var/log and its subdirectories.',answer:'find /var/log -name "*.log"',wrong:['grep "*.log" /var/log','ls /var/log/*.log','locate /var/log -name "*.log"'],tip:'Quote patterns such as "*.log" so the shell does not expand them too early.',examples:[['find . -type f','Find regular files beneath the current directory.'],['find . -type f -mtime -7','Find files modified less than seven days ago.']]},
  {id:'locate',level:'intermediate',group:'filesystem',about:'Searches an indexed filename database for paths; results may be stale.',syntax:'locate pattern',demo:'locate ssh_config',meaning:'Finds indexed pathnames containing ssh_config.',task:'Quickly search the indexed filename database for paths containing ssh_config.',answer:'locate ssh_config',wrong:['grep ssh_config /','find -index ssh_config','which ssh_config'],tip:'locate relies on a database. Fresh files might not appear until the index is updated.',examples:[['locate bashrc','Find indexed paths containing bashrc.'],['locate -i README','Search indexed paths without case sensitivity.']]},
  {id:'wc',level:'intermediate',group:'text',about:'Counts lines, words, bytes, or characters.',syntax:'wc [options] [file]',demo:'wc -l access.log',meaning:'Counts newline characters in access.log (often used as its line count).',task:'Count newline-delimited lines in access.log.',answer:'wc -l access.log',wrong:['grep -l access.log','sort -l access.log','head -l access.log'],tip:'wc -l counts newline characters; a file lacking a final newline can be surprising.',examples:[['wc -w essay.txt','Count whitespace-separated words.'],['wc -c data.bin','Count bytes.']]},
  {id:'sort',level:'intermediate',group:'text',about:'Sorts lines of text.',syntax:'sort [options] [file]',demo:'sort -n scores.txt',meaning:'Sorts the lines of scores.txt by numeric value.',task:'Sort the lines in scores.txt numerically, not lexicographically.',answer:'sort -n scores.txt',wrong:['sort scores.txt','uniq -n scores.txt','wc -n scores.txt'],tip:'Without -n, 100 may sort before 20 because sort normally compares text.',examples:[['sort names.txt','Sort lines alphabetically according to locale.'],['sort -nr scores.txt','Sort numeric values from highest to lowest.']]},
  {id:'uniq',level:'intermediate',group:'text',about:'Filters or counts adjacent duplicate lines.',syntax:'uniq [options] [file]',demo:'sort names.txt | uniq -c',meaning:'Sorts names and prints the count of each distinct line.',task:'Count occurrences of each distinct line in names.txt, regardless of its original order.',answer:'sort names.txt | uniq -c',wrong:['uniq -c names.txt','sort -c names.txt','wc -l names.txt'],tip:'uniq only compares adjacent lines. Sort first to group equal values together.',examples:[['sort names.txt | uniq','Display distinct values in sorted order.'],['uniq -d sorted.txt','Show only duplicate groups in already sorted input.']]},
  {id:'cut',level:'intermediate',group:'text',about:'Extracts fields or character ranges from each line.',syntax:'cut -d DELIMITER -f FIELDS [file]',demo:'cut -d: -f1 /etc/passwd',meaning:'Prints the first colon-separated field of each passwd line.',task:'Extract usernames (the first colon-separated field) from /etc/passwd.',answer:'cut -d: -f1 /etc/passwd',wrong:['cut -d: -f2 /etc/passwd','grep -d: -f1 /etc/passwd','sort -d: -f1 /etc/passwd'],tip:'-d specifies the delimiter, and -f selects the one-based field number.',examples:[['cut -d, -f2 data.csv','Extract the second comma-separated field (not a full CSV parser).'],['cut -c1-8 lines.txt','Show the first eight characters of each line.']]},
  {id:'tr',level:'intermediate',group:'text',about:'Translates or deletes characters from standard input.',syntax:'tr SET1 SET2',demo:'echo hello | tr a-z A-Z',meaning:'Converts lowercase letters in hello to uppercase.',task:'Convert lowercase ASCII letters from standard input to uppercase.',answer:'tr a-z A-Z',wrong:['sort a-z A-Z','cut a-z A-Z','uniq -u'],tip:'tr reads standard input, not filenames as ordinary positional arguments.',examples:[['echo hello | tr a-z A-Z','Produce HELLO.'],['echo "a   b" | tr -s " "','Compress repeated spaces to one space.']]},
  {id:'sed',level:'intermediate',group:'text',about:'Processes and transforms streams of text using editing expressions.',syntax:'sed [options] SCRIPT [file]',demo:'sed "s/cat/dog/g" pets.txt',meaning:'Prints pets.txt with every cat replaced by dog on each line.',task:'Print the contents of pets.txt, replacing every occurrence of cat with dog.',answer:'sed "s/cat/dog/g" pets.txt',wrong:['sed "s/cat/dog/" pets.txt','grep "cat/dog" pets.txt','tr "cat" "dog" pets.txt'],tip:'The g flag replaces every occurrence on a line; without it, only the first is replaced.',examples:[['sed -n "1,5p" file.txt','Print only lines 1 through 5.'],['sed "s/old/new/" file.txt','Replace the first old per line in output.']]},
  {id:'awk',level:'intermediate',group:'text',about:'Processes records and fields using a small programming language.',syntax:'awk PROGRAM [file]',demo:"awk '{print $1}' data.txt",meaning:'Prints the first whitespace-separated field of each input line.',task:'Print only the first whitespace-separated field from each line of data.txt.',answer:'awk \'{print $1}\' data.txt',wrong:['cut -d, -f1 data.txt','awk \'{print $0}\' data.txt','awk \'{print $2}\' data.txt'],tip:'In awk, $0 is the full record and $1 is the first field. Single quotes prevent shell expansion.',examples:[['awk \'{print $2}\' data.txt','Print the second whitespace-separated field.'],['awk -F: \'{print $1}\' /etc/passwd','Use a colon field separator.']]},
  {id:'tee',level:'intermediate',group:'text',about:'Copies standard input both to a file and to standard output.',syntax:'tee [options] file',demo:'echo ready | tee status.txt',meaning:'Writes ready to status.txt and also prints it to the terminal.',task:'Save the output of echo ready to status.txt while still seeing it on screen.',answer:'echo ready | tee status.txt',wrong:['echo ready > status.txt','cat status.txt > echo ready','echo ready | wc -c'],tip:'tee -a appends rather than overwriting a file.',examples:[['ls | tee listing.txt','Display a directory listing and save a copy.'],['echo next | tee -a status.txt','Append a line while printing it.']]},
  {id:'xargs',level:'intermediate',group:'shell',about:'Builds command arguments from standard input.',syntax:'xargs [options] command',demo:'printf "a\\nb\\n" | xargs -n 1 echo',meaning:'Runs echo once per input item using one argument each time.',task:'Pass one input item at a time as an argument to echo.',answer:'xargs -n 1 echo',wrong:['xargs -n 0 echo','tee -n 1 echo','uniq -n 1 echo'],tip:'Be careful with spaces and newlines in filenames. When supported, -0 pairs with NUL-delimited input.',examples:[['printf "a\\nb\\n" | xargs echo','Combine items into echo arguments.'],['find . -type f -print0 | xargs -0 -n1 basename','Safely pass filenames to basename one at a time.']]},
  {id:'diff',level:'intermediate',group:'text',about:'Shows line-by-line differences between two files.',syntax:'diff [options] file1 file2',demo:'diff -u before.txt after.txt',meaning:'Displays a unified-format comparison of the two text files.',task:'See changes between before.txt and after.txt using unified diff format.',answer:'diff -u before.txt after.txt',wrong:['comm -u before.txt after.txt','cat before.txt after.txt','sort -u before.txt after.txt'],tip:'Lines prefixed with + are additions and - are removals in unified diff output.',examples:[['diff a.txt b.txt','Compare two text files.'],['diff -r dir1 dir2','Recursively compare directory trees.']]},
  {id:'comm',level:'intermediate',group:'text',about:'Compares two sorted files and displays unique or common lines.',syntax:'comm [options] file1 file2',demo:'comm -12 sorted-a.txt sorted-b.txt',meaning:'Displays lines common to both sorted files.',task:'Print only the lines that appear in both already-sorted files.',answer:'comm -12 sorted-a.txt sorted-b.txt',wrong:['diff -12 sorted-a.txt sorted-b.txt','uniq sorted-a.txt sorted-b.txt','comm sorted-a.txt sorted-b.txt'],tip:'Input files should be sorted using the same collating order. -12 suppresses columns 1 and 2.',examples:[['comm a.txt b.txt','Show three columns: only A, only B, and shared (sorted inputs).'],['comm -23 a.txt b.txt','Show lines only in the first sorted file.']]},
  {id:'paste',level:'intermediate',group:'text',about:'Merges corresponding lines from input files side by side.',syntax:'paste [options] file1 file2',demo:'paste names.txt ages.txt',meaning:'Merges corresponding lines from two files into tab-separated columns.',task:'Combine each line from names.txt beside the matching line from ages.txt.',answer:'paste names.txt ages.txt',wrong:['cat names.txt ages.txt','diff names.txt ages.txt','sort names.txt ages.txt'],tip:'paste merges horizontally; cat concatenates contents vertically.',examples:[['paste -d, a.txt b.txt','Merge corresponding lines separated by a comma.'],['paste -s lines.txt','Join all lines of one file into a single row.']]},
  {id:'chmod',level:'intermediate',group:'filesystem',about:'Changes file or directory permission bits.',syntax:'chmod MODE path',demo:'chmod u+x deploy.sh',meaning:'Adds executable permission for the file owner on deploy.sh.',task:'Make deploy.sh executable by its owner without changing group or other permissions.',answer:'chmod u+x deploy.sh',wrong:['chmod a-w deploy.sh','chown u+x deploy.sh','chmod 777 deploy.sh'],tip:'Use symbolic modes such as u+x for narrow changes. 777 grants broad permissions and is rarely appropriate.',examples:[['chmod 600 secret.txt','Allow only the owner to read and write.'],['chmod g-w file.txt','Remove group write permission.']]},
  {id:'chown',level:'intermediate',group:'filesystem',about:'Changes a file or directory’s owner and optionally its group.',syntax:'chown OWNER[:GROUP] path',demo:'sudo chown alice:developers report.txt',meaning:'Sets report.txt owner to alice and group to developers.',task:'Set the owner of report.txt to alice and its group to developers.',answer:'sudo chown alice:developers report.txt',wrong:['chmod alice:developers report.txt','sudo chgrp alice report.txt','sudo chown developers:alice report.txt'],tip:'Changing ownership typically needs elevated privileges. chown is not the same as chmod.',examples:[['sudo chown alice file.txt','Set a file owner.'],['sudo chown -R alice:staff project/','Change ownership recursively; review the path carefully.']]},
  {id:'ln',level:'intermediate',group:'filesystem',about:'Creates hard links or symbolic links.',syntax:'ln [-s] TARGET LINK_NAME',demo:'ln -s /opt/app/current app-link',meaning:'Creates a symbolic link named app-link pointing at /opt/app/current.',task:'Create a symbolic link named app-link that points to /opt/app/current.',answer:'ln -s /opt/app/current app-link',wrong:['ln /opt/app/current app-link','cp /opt/app/current app-link','mv /opt/app/current app-link'],tip:'-s makes a symbolic link. Without -s, ln attempts a hard link, which has different rules.',examples:[['ln -s target shortcut','Create a relative symbolic link.'],['ls -l app-link','Inspect where a symbolic link points.']]},
  {id:'ps',level:'intermediate',group:'process',about:'Shows a snapshot of running processes.',syntax:'ps [options]',demo:'ps aux',meaning:'Lists processes across users with detailed process information.',task:'Display a detailed snapshot of processes from all users.',answer:'ps aux',wrong:['ps -p $$','jobs','kill -l'],tip:'ps displays a snapshot; top updates its process view continuously.',examples:[['ps -ef','Show all processes in full-format style.'],['ps -p $$','Inspect the current shell process by PID.']]},
  {id:'top',level:'intermediate',group:'process',about:'Displays a live updating view of processes and resource use.',syntax:'top',demo:'top',meaning:'Opens a continuously updating interactive process monitor.',task:'Monitor CPU and memory usage of running processes live in a terminal.',answer:'top',wrong:['ps -ef','free -h','df -h'],tip:'Press q to exit. Use ps when you want a one-time process snapshot.',examples:[['top','Monitor processes interactively.'],['top -p 1234','Focus top on a particular PID.']]},
  {id:'kill',level:'intermediate',group:'process',about:'Sends a signal to a process identified by PID.',syntax:'kill [-SIGNAL] PID',demo:'kill -TERM 1234',meaning:'Sends the SIGTERM termination request to process 1234.',task:'Ask process 1234 to terminate gracefully using SIGTERM.',answer:'kill -TERM 1234',wrong:['kill -KILL 1234','pkill -TERM 1234','kill -STOP 1234'],tip:'SIGTERM requests shutdown; SIGKILL stops a process forcibly and cannot be caught.',examples:[['kill 1234','Send SIGTERM by default.'],['kill -l','List known signals.']]},
  {id:'pgrep',level:'intermediate',group:'process',about:'Finds process IDs that match a name or other criteria.',syntax:'pgrep [options] pattern',demo:'pgrep -a python',meaning:'Displays PIDs and command lines of processes matching python.',task:'Find running Python processes and print their PIDs with command lines.',answer:'pgrep -a python',wrong:['pkill -a python','ps -p python','kill -a python'],tip:'pgrep searches processes. pkill sends signals to them.',examples:[['pgrep sshd','Find PIDs matching sshd.'],['pgrep -u alice','Find processes belonging to user alice.']]},
  {id:'pkill',level:'intermediate',group:'process',about:'Sends signals to processes matching selection criteria such as name.',syntax:'pkill [-SIGNAL] pattern',demo:'pkill -TERM -x myworker',meaning:'Sends SIGTERM to processes whose names exactly match myworker.',task:'Request graceful termination of processes named exactly myworker.',answer:'pkill -TERM -x myworker',wrong:['pgrep -x myworker','pkill -KILL -x myworker','kill -TERM myworker'],tip:'pkill can affect multiple processes. Use pgrep first to verify which PIDs match.',examples:[['pgrep -a myworker','Preview matching processes before signaling.'],['pkill -HUP -x myworker','Send SIGHUP to exact-name matches.']]},
  {id:'tar',level:'intermediate',group:'files',about:'Creates and extracts archive files; compression is optional.',syntax:'tar [options] [archive] [paths]',demo:'tar -czf backup.tar.gz docs/',meaning:'Creates a gzip-compressed tar archive from the docs directory.',task:'Pack docs/ into a gzip-compressed archive named backup.tar.gz.',answer:'tar -czf backup.tar.gz docs/',wrong:['tar -xzf backup.tar.gz docs/','gzip docs/ backup.tar.gz','tar -cf backup.tar.gz docs/'],tip:'c creates, x extracts, z enables gzip, f specifies the archive filename.',examples:[['tar -xzf backup.tar.gz','Extract a gzip-compressed tar archive.'],['tar -tf archive.tar','List files stored inside a tar archive.']]},
  {id:'gzip',level:'intermediate',group:'files',about:'Compresses files using gzip format.',syntax:'gzip [options] file',demo:'gzip -k report.txt',meaning:'Creates report.txt.gz while keeping the original report.txt.',task:'Compress report.txt with gzip but retain the uncompressed original.',answer:'gzip -k report.txt',wrong:['gzip report.txt','gunzip report.txt','tar -xf report.txt'],tip:'Without -k, gzip normally replaces the input file with its .gz version.',examples:[['gzip large.log','Compress large.log and normally remove the original.'],['gzip -9 -k report.txt','Keep the original while using a stronger compression setting.']]},
  {id:'gunzip',level:'intermediate',group:'files',about:'Decompresses gzip-compressed files.',syntax:'gunzip [options] file.gz',demo:'gunzip -k report.txt.gz',meaning:'Decompresses report.txt.gz while keeping the .gz file.',task:'Extract report.txt.gz without deleting the compressed original.',answer:'gunzip -k report.txt.gz',wrong:['gzip -k report.txt.gz','gunzip report.txt.gz','tar -cf report.txt.gz'],tip:'Without -k, gunzip normally removes the compressed input when successful.',examples:[['gunzip archive.log.gz','Restore a compressed log file.'],['gzip -dc file.gz','Print decompressed content to stdout.']]},
  {id:'curl',level:'intermediate',group:'network',about:'Transfers data to or from URLs and can make HTTP requests.',syntax:'curl [options] URL',demo:'curl -I https://example.com',meaning:'Requests and displays HTTP response headers without downloading the body.',task:'Inspect HTTP response headers for https://example.com.',answer:'curl -I https://example.com',wrong:['curl -O https://example.com','wget https://example.com','ping https://example.com'],tip:'-I performs a HEAD request for HTTP URLs. -L follows redirects.',examples:[['curl https://example.com','Fetch a URL to standard output.'],['curl -L -o page.html https://example.com','Follow redirects and save the response body.']]},
  {id:'wget',level:'intermediate',group:'network',about:'Downloads files over HTTP, HTTPS, and other supported protocols.',syntax:'wget [options] URL',demo:'wget -O index.html https://example.com',meaning:'Downloads a URL and saves its response as index.html.',task:'Download https://example.com to a local file named index.html.',answer:'wget -O index.html https://example.com',wrong:['wget -q https://example.com','curl -I https://example.com','wget -P index.html https://example.com'],tip:'Uppercase -O sets a specific output filename; -P selects a directory.',examples:[['wget https://example.com/file.zip','Download a file with the server-derived filename.'],['wget -c https://example.com/big.iso','Try to resume a partially downloaded file.']]},
  {id:'ssh',level:'intermediate',group:'network',about:'Starts encrypted remote shell sessions.',syntax:'ssh [user@]host',demo:'ssh alice@server.example',meaning:'Starts an SSH connection to server.example as user alice.',task:'Open an encrypted remote shell on server.example as user alice.',answer:'ssh alice@server.example',wrong:['scp alice@server.example','curl alice@server.example','ssh server.example@alice'],tip:'SSH servers typically listen on port 22, but the configured port can differ.',examples:[['ssh -p 2222 alice@server.example','Connect to a server using port 2222.'],['ssh alice@server.example uptime','Run one remote command and display its output.']]},
  {id:'scp',level:'intermediate',group:'network',about:'Copies files over SSH between local and remote machines.',syntax:'scp source destination',demo:'scp report.txt alice@server:/tmp/',meaning:'Copies the local report.txt to /tmp/ on the remote server.',task:'Securely upload local report.txt into /tmp/ on server as alice.',answer:'scp report.txt alice@server:/tmp/',wrong:['ssh report.txt alice@server:/tmp/','scp alice@server:/tmp/report.txt .','cp report.txt alice@server:/tmp/'],tip:'In scp syntax, host:path identifies a remote location. Confirm destinations before overwriting.',examples:[['scp alice@server:/tmp/report.txt .','Download a remote file into the current directory.'],['scp -r folder/ alice@server:/tmp/','Copy a directory recursively over SSH.']]},
  // ───────────────────────────── ADVANCED ─────────────────────────────
  {id:'systemctl',level:'advanced',group:'system',about:'Controls systemd services, units, and system state.',syntax:'systemctl ACTION [unit]',demo:'systemctl status ssh.service',meaning:'Shows the current status and recent details of the SSH service.',task:'Inspect the state of the SSH service on a systemd-based Linux system.',answer:'systemctl status ssh.service',wrong:['systemctl restart ssh.service','journalctl -f ssh.service','ps ssh.service'],tip:'systemctl is for systemd-based systems. status inspects without restarting the unit.',examples:[['sudo systemctl restart nginx','Restart the nginx systemd service.'],['systemctl list-units --type=service','List currently loaded service units.']]},
  {id:'journalctl',level:'advanced',group:'system',about:'Queries logs stored by systemd-journald.',syntax:'journalctl [options]',demo:'journalctl -u ssh.service -n 50',meaning:'Displays the most recent 50 journal entries for the SSH service.',task:'Read the last 50 systemd journal entries for ssh.service.',answer:'journalctl -u ssh.service -n 50',wrong:['journalctl -n 50','systemctl status -n 50','tail -n 50 ssh.service'],tip:'-u filters to a unit; -f follows new messages; -b restricts to a boot.',examples:[['journalctl -b','View journal entries from the current boot.'],['journalctl -u nginx -f','Follow live journal entries for the nginx unit.']]},
  {id:'ss',level:'advanced',group:'network',about:'Inspects network sockets, listening ports, and active connections.',syntax:'ss [options]',demo:'ss -tulpn',meaning:'Lists listening TCP/UDP sockets, with numeric addresses and process info when permitted.',task:'Inspect listening TCP and UDP ports and their associated processes when permitted.',answer:'ss -tulpn',wrong:['ss -tan','ip -br addr','dig -t A localhost'],tip:'-t TCP, -u UDP, -l listening, -p process, -n numeric. Process details may require privileges.',examples:[['ss -tan','List TCP sockets with numeric addresses.'],['ss -ltn','List listening TCP sockets numerically.']]},
  {id:'lsof',level:'advanced',group:'process',about:'Lists files and sockets opened by processes.',syntax:'lsof [options]',demo:'lsof -i :8080',meaning:'Shows processes with network endpoints using port 8080.',task:'Find processes using network port 8080.',answer:'lsof -i :8080',wrong:['ls -f :8080','ss -f :8080','ip -i :8080'],tip:'lsof can also identify which process has a regular file open. Visibility depends on permissions.',examples:[['lsof /var/log/app.log','Find processes holding a particular file open.'],['lsof -p 1234','List files opened by PID 1234.']]},
  {id:'ip',level:'advanced',group:'network',about:'Displays and configures interfaces, addresses, and routes.',syntax:'ip OBJECT COMMAND',demo:'ip route show',meaning:'Displays the system routing table.',task:'Display the kernel IP routing table.',answer:'ip route show',wrong:['ip addr add','ss -r','dig route'],tip:'ip addr lists addresses; ip route lists routes. Configuration changes may require sudo.',examples:[['ip -br addr','Show a compact view of interface addresses.'],['ip link show','List network link interfaces.']]},
  {id:'dig',level:'advanced',group:'network',about:'Queries DNS servers for records.',syntax:'dig [@server] name [type]',demo:'dig example.com MX',meaning:'Queries the DNS MX records for example.com.',task:'Look up mail-exchange (MX) DNS records for example.com.',answer:'dig example.com MX',wrong:['dig example.com A','ss example.com MX','ping example.com MX'],tip:'DNS record types matter: A is IPv4 address; AAAA is IPv6; MX is mail routing.',examples:[['dig example.com A','Query IPv4 address records.'],['dig +short example.com','Return concise DNS answers.']]},
  {id:'tcpdump',level:'advanced',group:'network',about:'Captures and inspects network packets on an interface.',syntax:'tcpdump [options] [filter]',demo:'sudo tcpdump -i eth0 port 53',meaning:'Captures packets on eth0 involving port 53, commonly DNS traffic.',task:'Capture packets on eth0 that use port 53.',answer:'sudo tcpdump -i eth0 port 53',wrong:['ss -i eth0 port 53','tcpdump -i eth0 port 80','dig -i eth0 port 53'],tip:'Packet capture normally requires privileges. Only capture traffic you are authorized to inspect.',examples:[['sudo tcpdump -i any -c 10','Capture ten packets across available interfaces on Linux.'],['sudo tcpdump -nn -i eth0 tcp','Show TCP packets without resolving addresses.']]},
  {id:'rsync',level:'advanced',group:'files',about:'Efficiently copies and synchronizes file trees locally or remotely.',syntax:'rsync [options] SOURCE DEST',demo:'rsync -av photos/ backup/',meaning:'Copies the contents of photos/ into backup/ recursively while preserving key metadata.',task:'Sync the contents of photos/ into backup/ in archive mode with verbose output.',answer:'rsync -av photos/ backup/',wrong:['rsync -av photos backup/','cp -v photos/ backup/','rsync -av backup/ photos/'],tip:'A trailing slash on the source changes whether the directory itself or its contents are copied.',examples:[['rsync -avn photos/ backup/','Preview synchronization changes without writing.'],['rsync -av --delete a/ b/','Mirror a into b, deleting extras in b; use with extreme care.']]},
  {id:'crontab',level:'advanced',group:'system',about:'Edits or lists user-specific recurring cron schedules.',syntax:'crontab [-e|-l|-r]',demo:'crontab -l',meaning:'Lists cron jobs configured in the current user’s crontab.',task:'View the scheduled cron entries installed for your user.',answer:'crontab -l',wrong:['crontab -e','crontab -r','at -l'],tip:'crontab -r removes the user crontab; -e edits it. Cron availability depends on the system.',examples:[['crontab -e','Edit your user crontab.'],['0 9 * * 1 /path/script.sh','Example crontab line: run at 09:00 every Monday.']]},
  {id:'at',level:'advanced',group:'system',about:'Queues a one-time job for later execution when atd is available.',syntax:'at TIME',demo:'echo "date > /tmp/ran-at.txt" | at now + 5 minutes',meaning:'Schedules a one-time date command to run about five minutes later.',task:'Schedule the command date to run once five minutes from now.',answer:'echo date | at now + 5 minutes',wrong:['crontab -e','echo date | at now - 5 minutes','watch -n 300 date'],tip:'at requires the at utility and its scheduler service. It is for one-off jobs, unlike recurring cron.',examples:[['atq','List queued at jobs.'],['atrm 3','Remove queued at job number 3.']]},
  {id:'nohup',level:'advanced',group:'process',about:'Runs a command with hangup signals ignored, often used for long-running jobs.',syntax:'nohup COMMAND [args...] &',demo:'nohup ./worker.sh > worker.log 2>&1 &',meaning:'Starts worker.sh in the background, ignoring SIGHUP and redirecting output.',task:'Launch worker.sh in the background so it ignores terminal hangups, logging stdout and stderr.',answer:'nohup ./worker.sh > worker.log 2>&1 &',wrong:['./worker.sh > worker.log','nohup ./worker.sh > worker.log','fg ./worker.sh'],tip:'nohup does not daemonize by itself; & backgrounds the process, and redirection controls output.',examples:[['nohup longjob &','Start a job ignoring SIGHUP in the background.'],['tail -f worker.log','Watch the redirected output.']]},
  {id:'nice',level:'advanced',group:'process',about:'Starts a process with a chosen CPU scheduling nice value.',syntax:'nice -n ADJUSTMENT COMMAND',demo:'nice -n 10 ./heavy-task',meaning:'Runs heavy-task with an increased nice value and generally lower CPU priority.',task:'Start heavy-task with a lower CPU scheduling priority using nice value 10.',answer:'nice -n 10 ./heavy-task',wrong:['renice 10 ./heavy-task','nice -n -10 ./heavy-task','priority -n 10 ./heavy-task'],tip:'Higher nice values generally mean lower priority. Decreasing a nice value may require privileges.',examples:[['nice -n 5 make','Run a build with an increased nice value.'],['nice','Show the default nice value in many implementations.']]},
  {id:'renice',level:'advanced',group:'process',about:'Changes the nice value of an already running process.',syntax:'renice PRIORITY -p PID',demo:'renice 10 -p 4321',meaning:'Sets the nice value of running process 4321 to 10, if permitted.',task:'Change the nice value of existing process 4321 to 10.',answer:'renice 10 -p 4321',wrong:['nice -n 10 4321','renice -p 10 4321','kill -10 4321'],tip:'nice starts a new process; renice adjusts a running one.',examples:[['renice 15 -p 1234','Lower CPU priority of a running process when authorized.'],['ps -o pid,ni,comm -p 1234','Inspect its PID, nice value, and command name.']]},
  {id:'jobs',level:'advanced',group:'shell',about:'Lists jobs managed by the current interactive shell.',syntax:'jobs [options]',demo:'jobs -l',meaning:'Lists the shell’s background/stopped jobs and their PIDs.',task:'See the active shell jobs with their associated PIDs.',answer:'jobs -l',wrong:['ps aux','top -p','bg -l'],tip:'jobs only reports processes managed by the current shell, not all processes on the machine.',examples:[['jobs','Show jobs belonging to your current shell.'],['jobs -r','Show running shell jobs in Bash.']]},
  {id:'bg',level:'advanced',group:'shell',about:'Resumes a suspended shell job in the background.',syntax:'bg [%job]',demo:'bg %1',meaning:'Resumes shell job number 1 in the background.',task:'Resume stopped job number 1 without bringing it to the foreground.',answer:'bg %1',wrong:['fg %1','jobs %1','kill %1'],tip:'Use Ctrl+Z to suspend an interactive foreground job, then bg to continue it in the background.',examples:[['bg','Resume the current job in the background.'],['jobs','Check job numbers and states.']]},
  {id:'fg',level:'advanced',group:'shell',about:'Brings a shell-managed job into the foreground.',syntax:'fg [%job]',demo:'fg %1',meaning:'Brings shell job number 1 to the foreground.',task:'Return job number 1 to the foreground of your terminal.',answer:'fg %1',wrong:['bg %1','jobs -l %1','disown %1'],tip:'fg reconnects a job to the foreground terminal. The job must belong to your current shell.',examples:[['fg','Bring the current job to the foreground.'],['fg %2','Foreground shell job number 2.']]},
  {id:'disown',level:'advanced',group:'shell',about:'Removes jobs from the shell job table, or changes hangup behavior in Bash.',syntax:'disown [-h] [%job]',demo:'disown -h %1',meaning:'Marks Bash job 1 so the shell does not send it SIGHUP when exiting.',task:'Keep Bash from sending SIGHUP to shell job number 1 when the shell exits.',answer:'disown -h %1',wrong:['fg %1','kill -HUP %1','bg -h %1'],tip:'disown is a shell builtin, not a universal external Linux command; behavior varies by shell.',examples:[['disown %1','Remove job 1 from the Bash job table.'],['jobs -l','See jobs before disowning one.']]},
  {id:'watch',level:'advanced',group:'system',about:'Runs a command repeatedly and displays its updated output.',syntax:'watch [-n SECONDS] COMMAND',demo:'watch -n 2 df -h',meaning:'Refreshes the human-readable filesystem usage output every two seconds.',task:'Repeatedly display disk usage with a two-second refresh interval.',answer:'watch -n 2 df -h',wrong:['df -h -n 2','watch -n 2 du -sh','timeout 2 df -h'],tip:'watch is for periodic viewing. Press Ctrl+C to exit.',examples:[['watch -n 1 date','Refresh the date/time output every second.'],['watch -d -n 2 free -h','Highlight changes while watching memory usage.']]},
  {id:'timeout',level:'advanced',group:'process',about:'Runs a command with a time limit and can send a termination signal on expiry.',syntax:'timeout DURATION COMMAND',demo:'timeout 5s sleep 60',meaning:'Runs sleep 60 but sends a termination signal after five seconds.',task:'Limit a potentially long-running sleep 60 command to five seconds.',answer:'timeout 5s sleep 60',wrong:['sleep 5s sleep 60','watch -n 5 sleep 60','nohup sleep 60'],tip:'timeout usually sends SIGTERM on expiry; use -k for a later SIGKILL grace period.',examples:[['timeout 10s curl https://example.com','Give the overall curl command ten seconds.'],['timeout -k 2s 10s ./job','Send TERM after 10 seconds and KILL two seconds later if needed.']]},
  {id:'env',level:'advanced',group:'shell',about:'Prints the environment or launches a command with a modified environment.',syntax:'env [NAME=VALUE ...] [COMMAND]',demo:'env MODE=test ./app',meaning:'Runs ./app with MODE set to test in its environment.',task:'Launch ./app with MODE=test without permanently setting that variable in your shell.',answer:'env MODE=test ./app',wrong:['export MODE=test ./app','echo MODE=test ./app','alias MODE=test ./app'],tip:'NAME=value before a command sets the environment for that invocation; env also prints variables on its own.',examples:[['env','Show environment variables.'],['env -u DEBUG ./app','Start an app with DEBUG removed from its environment.']]},
  {id:'export',level:'advanced',group:'shell',about:'Marks shell variables to be inherited by child processes.',syntax:'export NAME=VALUE',demo:'export APP_ENV=staging',meaning:'Sets APP_ENV to staging and exports it to child processes in the current shell.',task:'Make APP_ENV=staging available to programs launched afterward from your shell.',answer:'export APP_ENV=staging',wrong:['echo APP_ENV=staging','alias APP_ENV=staging','env -u APP_ENV'],tip:'export changes the environment of the current shell and its future children, not already-running processes.',examples:[['export PATH="$HOME/bin:$PATH"','Add a home bin directory to PATH for future commands.'],['export -p','List exported variables in Bash.']]},
  {id:'alias',level:'advanced',group:'shell',about:'Defines a short replacement for a longer command in a shell.',syntax:'alias NAME=VALUE',demo:'alias ll="ls -lah"',meaning:'Creates a shell alias ll that expands to ls -lah.',task:'Create a shell shortcut named ll that runs ls -lah.',answer:'alias ll="ls -lah"',wrong:['export ll="ls -lah"','env ll="ls -lah"','alias ls -lah ll'],tip:'Aliases are typically scoped to the current shell unless added to shell startup configuration.',examples:[['alias','List current aliases in Bash.'],['unalias ll','Remove the ll alias.']]},
  {id:'source',level:'advanced',group:'shell',about:'Executes commands from a file in the current shell context.',syntax:'source FILE',demo:'source ~/.bashrc',meaning:'Executes ~/.bashrc in the current shell, applying shell changes immediately.',task:'Reload changes from ~/.bashrc into your current Bash session.',answer:'source ~/.bashrc',wrong:['bash ~/.bashrc','cat ~/.bashrc','chmod +x ~/.bashrc'],tip:'source runs in the current shell; launching bash as a separate process does not apply its environment changes to the parent.',examples:[['. ~/.bashrc','POSIX-style dot syntax for sourcing a file.'],['source ./vars.sh','Load variable definitions into the current shell.']]},
  {id:'ulimit',level:'advanced',group:'system',about:'Reads or changes resource limits for the current shell and its children.',syntax:'ulimit [options] [limit]',demo:'ulimit -n',meaning:'Shows the current soft limit on open file descriptors.',task:'Check the soft limit for how many files a process can hold open.',answer:'ulimit -n',wrong:['lsof -n','ulimit -u','free -n'],tip:'ulimit is a shell builtin; hard limit changes may require elevated privileges.',examples:[['ulimit -a','Display current shell resource limits.'],['ulimit -Sn 4096','Attempt to set the soft open-file limit to 4096.']]},
  {id:'mount',level:'advanced',group:'system',about:'Attaches a filesystem to a location in the directory tree.',syntax:'mount [options] DEVICE DIRECTORY',demo:'sudo mount /dev/sdb1 /mnt/usb',meaning:'Mounts the filesystem on /dev/sdb1 at /mnt/usb.',task:'Attach the filesystem on /dev/sdb1 at /mnt/usb.',answer:'sudo mount /dev/sdb1 /mnt/usb',wrong:['sudo umount /mnt/usb','sudo lsblk /dev/sdb1 /mnt/usb','sudo mkdir /dev/sdb1 /mnt/usb'],tip:'Use lsblk/blkid to verify device identity before mounting. A wrong device selection can cause problems.',examples:[['mount | head','Show the beginning of the current mount list.'],['mount -o ro /dev/sdb1 /mnt/usb','Mount a filesystem read-only when supported.']]},
  {id:'umount',level:'advanced',group:'system',about:'Detaches a mounted filesystem from the directory tree.',syntax:'umount DEVICE_OR_MOUNTPOINT',demo:'sudo umount /mnt/usb',meaning:'Unmounts the filesystem currently mounted at /mnt/usb.',task:'Safely detach the filesystem mounted at /mnt/usb after closing open files.',answer:'sudo umount /mnt/usb',wrong:['sudo mount /mnt/usb','sudo rm -r /mnt/usb','sudo lsblk /mnt/usb'],tip:'The command is umount (without n). A busy filesystem may refuse to unmount.',examples:[['findmnt /mnt/usb','Check what is mounted at that directory.'],['sudo umount /dev/sdb1','Unmount a filesystem by device name.']]},
  {id:'lsblk',level:'advanced',group:'system',about:'Displays block-device hierarchy, sizes, and mount points.',syntax:'lsblk [options]',demo:'lsblk -f',meaning:'Lists block devices along with filesystem types, labels, UUIDs, and mounts.',task:'Inspect disks and partitions together with their filesystem types and UUIDs.',answer:'lsblk -f',wrong:['df -f','blkid -r','ls -f /dev'],tip:'lsblk focuses on block devices. df focuses on filesystem capacity.',examples:[['lsblk','Show disks and partitions in a tree.'],['lsblk -o NAME,SIZE,TYPE,MOUNTPOINTS','Select specific display columns.']]},
  {id:'blkid',level:'advanced',group:'system',about:'Finds block-device filesystem metadata such as UUID and TYPE.',syntax:'blkid [device]',demo:'sudo blkid /dev/sdb1',meaning:'Shows filesystem metadata, such as UUID and type, for /dev/sdb1.',task:'Inspect the filesystem UUID and type of partition /dev/sdb1.',answer:'sudo blkid /dev/sdb1',wrong:['lsblk /dev/sdb1 -u','df -u /dev/sdb1','file -u /dev/sdb1'],tip:'UUIDs are useful for stable mount configuration; device names can change.',examples:[['sudo blkid','List discoverable block-device identifiers.'],['sudo blkid -s UUID -o value /dev/sdb1','Print only the UUID value for a device.']]},
  {id:'useradd',level:'advanced',group:'admin',about:'Creates a local Linux user account with specified settings.',syntax:'useradd [options] LOGIN',demo:'sudo useradd -m trainee',meaning:'Creates local user trainee and requests a home directory.',task:'Create a local user named trainee with a home directory.',answer:'sudo useradd -m trainee',wrong:['sudo usermod -m trainee','sudo groupadd -m trainee','sudo useradd -M trainee'],tip:'On many distributions, passwd trainee is a separate step to set a password. Do not run examples on production systems.',examples:[['sudo useradd -m -s /bin/bash trainee','Create a user with a home directory and Bash as login shell.'],['id trainee','Inspect a user account after creation.']]},
  {id:'usermod',level:'advanced',group:'admin',about:'Modifies properties of an existing local Linux user account.',syntax:'usermod [options] LOGIN',demo:'sudo usermod -aG developers trainee',meaning:'Appends trainee to the supplementary developers group.',task:'Add existing user trainee to supplementary group developers without dropping other groups.',answer:'sudo usermod -aG developers trainee',wrong:['sudo usermod -G developers trainee','sudo useradd -G developers trainee','sudo groupadd trainee developers'],tip:'-aG appends a supplementary group. -G without -a can replace existing supplementary group memberships.',examples:[['sudo usermod -s /bin/bash trainee','Set the user’s login shell to Bash.'],['id trainee','Verify user group memberships.']]}
];
